field.placeholder:
🔔 New Order
📋 Order: ${name}
👤 Customer: ${partner_id.name}
💰 Total: ${amount_total}

📦 Items:
{% for line in order_line %}
- ${line.product_id.name} x ${line.product_uom_qty} = ${line.price_subtotal}
{% endfor %}

div.pre:
log(f"Iniciando procesamiento para el pedido {record.name}") record = records[0] if records else None
if not record: raise UserError("No se encontró ningún pedido de venta en 'records' para ejecutar esta acción.")
tareas_creadas = []
for line in record.order_line: proyecto = env['project.project'].search([('name', '=', 'Proyectos Web')], limit=1)
if proyecto: fecha_limite = date.today() + timedelta(days=7)
nueva_tarea = env['project.task'].create({ 'name': f"Servicio contratado: {line.product_id.name} ({record.name})", 'project_id': proyecto.id, 'partner_id': record.partner_id.id, 'date_deadline': fecha_limite, 'description': f"Tarea generada automáticamente desde el pedido {record.name}.", }) tareas_creadas.append(nueva_tarea.name)
if tareas_creadas: chat_id = self.chat_id or self.config_id.default_chat_id message = ( "Acción Automática:" "Se crearon las siguientes tareas:\n" + "\n".join(f"• {t}" for t in tareas_creadas) )
payload = { "chat_id": chat_id, "text": message, "parse_mode": "HTML", "reply_markup": { "inline_keyboard": [ [{'text': 'Opción A', 'callback_data': 'opcion_a'}], [{'text': 'Opción B', 'callback_data': 'opcion_b'}], [{'text': 'Hablar con soporte', 'callback_data': 'soporte'}] ] } } # Metodo POST/Request url =f"https://api.telegram.org/bot{self.config_id.bot_token}/sendMessage" _logger.info("Ejecutando url : %s", url) response = requests.post(url, json=payload, timeout=15 ) # Metodo nativo # Intenta obtener la respuesta estructurada de Telegram # res_data = response.json() if response.content else {} chat_id = self.chat_id or self.config_id.default_chat_id self.config_id.send_message(message, chat_id=chat_id) record.message_post(body=message)
